  // ===== lamps, plumbing (shower, taps, tub), mirror, curtain, switch, mailbox, water tank =====
  // Moving pieces come out as named parts (userData.part) with the pivot at the hinge/axis; see part() and applyPart() in 10-geom.js.
  function hashString(s) { let h = 2166136261; for (const ch of String(s)) h = Math.imul(h ^ ch.charCodeAt(0), 16777619); return h >>> 0; }
  function rngString(s) { let h = hashString(s) || 1; return () => { h = (h + 0x6D2B79F5) | 0; let t = Math.imul(h ^ (h >>> 15), 1 | h); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
  const SEED = () => (shared.ctx.r && shared.ctx.r.seed) || 0;
