    const K = kit2(M, A, M.y || 0), color = colorTemperature(M), id = 'lamp_pe_' + M.seed, h = Math.min(1.6, M.h || 1.5), meta = { id, room: M.room, on: !!M.on, color, lightType: 'floor', hidden: !M.on };
