    const K = kit2(M, A, M.y || 2.2), color = colorTemperature(M), id = 'lamp_ext_' + M.seed, structure = STYLE(), meta = { id, room: 'outside', on: !!M.on, color, lightType: 'outdoor', hidden: !M.on };
